using System;using System.IO;using System.Linq;using System.Text;using UnityEditor;using UnityEngine;
[InitializeOnLoad]public static class FinalBusPaintSampling{
static FinalBusPaintSampling(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalBusPaintSampling.request")||EditorApplication.isCompiling)return;File.Delete("FinalBusPaintSampling.request");var log=new StringBuilder();try{const string path="Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City Road Detail Atlas.png";var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.streamingMipmaps=false;importer.mipmapEnabled=true;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=8;importer.SaveAndReimport();var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Markings.mat");int errors=ShaderUtil.GetShaderMessages(mat.shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);AssetDatabase.SaveAssets();File.WriteAllText("FinalCitywideStops.request","verify");File.WriteAllText("FinalSunkenUnderpasses.request","finalcheck");log.AppendLine("SUCCESS: atlas mip chain resident (streaming disabled), trilinear/aniso 8 sampling; explicit continuous atlas gradients; smooth red bus paint without fine wear speckles; shader errors=0. Shared PNG and prefabs retained.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/BusPaintSamplingFix.txt",log.ToString());}
}
